const body = $input.first().json.body ?? $input.first().json;

let phone = '';
let messageText = '';

try {
  const data = body.data ?? body;
  const key = data.key ?? {};
  const message = data.message ?? {};
  const remoteJid = key.remoteJid ?? '';

  // Ignorar mensagens de grupos
  if (remoteJid.includes('@g.us')) {
    return [{ json: { ignore: true } }];
  }

  phone = remoteJid
    .replace('@s.whatsapp.net', '')
    .replace(/\D/g, '');

  messageText =
    message.conversation ||
    (message.extendedTextMessage && message.extendedTextMessage.text) ||
    '';

  if (!messageText.trim() || !phone) {
    return [{ json: { ignore: true } }];
  }

} catch (e) {
  return [{ json: { ignore: true, error: e.message } }];
}

return [{
  json: {
    phone,
    messageText: messageText.trim(),
    messageLower: messageText.trim().toLowerCase(),
    ignore: false
  }
}];

const parsed = $('Extrair Mensagem').first().json;
const usersData = $input.first().json;

if (parsed.ignore) {
  return [{ json: { route: 'ignore' } }];
}

const { phone, messageText, messageLower } = parsed;
const userList = Array.isArray(usersData) ? usersData : [];
const user = userList.length > 0 ? userList[0] : null;

if (!user) {
  return [{ json: { route: 'new_user', phone, messageText, messageLower, user: null } }];
}

if (!user.onboarding_complete) {
  return [{ json: { route: 'onboarding', phone, messageText, messageLower, user } }];
}

// Detecção de intenção
const EXPENSE_KW    = ['gastei', 'paguei', 'comprei', 'torrei', 'acabei de gastar', 'gastando'];
const MONTHLY_KW    = ['quanto gastei esse mês', 'resumo do mês', 'meu saldo', 'situação financeira', 'gastos do mês', 'como to esse mes', 'como estou esse mês', 'quanto gastei no mes'];
const CAT_KW        = ['quanto gastei com', 'quanto gastei no', 'quanto gastei na', 'gasto com '];
const ANNUAL_KW     = ['esse ano', 'resumo anual', 'total do ano', 'quanto gastei esse ano'];

let intent = 'unknown';
if (EXPENSE_KW.some(k => messageLower.includes(k)))      intent = 'expense';
else if (MONTHLY_KW.some(k => messageLower.includes(k))) intent = 'monthly_summary';
else if (CAT_KW.some(k => messageLower.includes(k)))     intent = 'category_spending';
else if (ANNUAL_KW.some(k => messageLower.includes(k)))  intent = 'annual_summary';

return [{ json: { route: intent, phone, messageText, messageLower, user } }];

const routeData = $('Lógica de Roteamento').first().json;
const { user, messageText, messageLower, phone } = routeData;
const step = user.onboarding_step || 1;

// ⚠️ CONFIGURE: Substitua pelos UUIDs reais das categorias no seu Supabase
// Execute: SELECT id, name FROM categories ORDER BY name no Supabase
const CATEGORIES = [
  { step: 1, name: 'Alimentação',  emoji: '🍔', id: 'UUID_ALIMENTACAO'  },
  { step: 2, name: 'Transporte',   emoji: '🚗', id: 'UUID_TRANSPORTE'   },
  { step: 3, name: 'Lazer',        emoji: '🎮', id: 'UUID_LAZER'        },
  { step: 4, name: 'Saúde',        emoji: '💊', id: 'UUID_SAUDE'        },
  { step: 5, name: 'Moradia',      emoji: '🏠', id: 'UUID_MORADIA'      },
  { step: 6, name: 'Roupas',       emoji: '👕', id: 'UUID_ROUPAS'       },
  { step: 7, name: 'Educação',     emoji: '📚', id: 'UUID_EDUCACAO'     }
];

// Extrair valor numérico da mensagem do usuário
const amountMatch = messageLower.match(/(\d+[,.]?\d*)/);
const amount = amountMatch ? parseFloat(amountMatch[1].replace(',', '.')) : 0;

const currentCat = CATEGORIES.find(c => c.step === step);
const newStep    = step + 1;
const isLastStep = newStep > 7;

let nextMessage = '';
if (!isLastStep) {
  const nextCat = CATEGORIES.find(c => c.step === newStep);
  nextMessage = `✅ Anotado! Agora me fala:\n\nQuanto você vai gastar por mês em *${nextCat.name}* ${nextCat.emoji}?`;
} else {
  nextMessage = `✅ *Briefing concluído, recruta!*\n\nAgora toda vez que gastar, me manda:\n\n*"General, gastei 50 reais no iFood"*\n\nE eu registro e te xingo quando necessário. Pode começar! 🎖️`;
}

return [{
  json: {
    phone,
    userId: user.id,
    categoryId: currentCat ? currentCat.id : null,
    budgetAmount: amount,
    newStep,
    onboardingComplete: isLastStep,
    nextMessage
  }
}];

const routeData = $('Lógica de Roteamento').first().json;
const { user, messageText, messageLower, phone } = routeData;

// Extrair valor da mensagem
const amountPatterns = [
  /r\$\s*(\d+[.,]\d{2})/i,
  /r\$\s*(\d+)/i,
  /(\d+[.,]\d{2})\s*(?:reais?|r\$)?/i,
  /(\d+)\s*reais/i,
  /(\d+)/
];

let amount = 0;
for (const pattern of amountPatterns) {
  const match = messageLower.match(pattern);
  if (match) {
    amount = parseFloat(match[1].replace(',', '.'));
    break;
  }
}

// Extrair descrição
let description = '';
const descPatterns = [
  /(?:gastei|paguei|comprei|torrei)[^0-9]*(?:\d+[.,]?\d*\s*(?:reais?|r\$)?\s*)?(?:em|no|na|com|de|pra|num|numa)?\s*(.+)/i,
  /(?:em|no|na|com|de)\s+(.+)$/i
];
for (const pattern of descPatterns) {
  const match = messageText.match(pattern);
  if (match && match[1]) { description = match[1].trim(); break; }
}
if (!description) description = messageText;

// ⚠️ CONFIGURE: Substitua pelos UUIDs reais das suas categorias no Supabase
const CATEGORIES = [
  { name: 'Alimentação', id: 'UUID_ALIMENTACAO', keywords: ['ifood', 'restaurante', 'lanche', 'almoço', 'jantar', 'mercado', 'padaria', 'pizza', 'hamburguer', 'burger', 'comida', 'refeição', 'churrasco', 'sushi', 'marmita', 'açaí', 'pastel', 'cafe', 'café'] },
  { name: 'Transporte',  id: 'UUID_TRANSPORTE',  keywords: ['uber', '99', 'taxi', 'gasolina', 'combustivel', 'onibus', 'metro', 'estacionamento', 'pedagio', 'posto', 'metrô', 'ônibus'] },
  { name: 'Lazer',       id: 'UUID_LAZER',       keywords: ['netflix', 'spotify', 'cinema', 'show', 'jogo', 'bar', 'balada', 'viagem', 'hotel', 'ingresso', 'streaming', 'prime', 'disney', 'youtube', 'game', 'festa', 'choperia'] },
  { name: 'Saúde',       id: 'UUID_SAUDE',       keywords: ['farmacia', 'remedio', 'consulta', 'medico', 'academia', 'dentista', 'exame', 'plano de saude', 'hospital', 'clinica', 'drogaria'] },
  { name: 'Moradia',     id: 'UUID_MORADIA',     keywords: ['aluguel', 'condominio', 'conta de luz', 'agua', 'internet', 'gas', 'luz', 'energia', 'boleto', 'iptu', 'net', 'claro', 'vivo', 'tim'] },
  { name: 'Roupas',      id: 'UUID_ROUPAS',      keywords: ['roupa', 'tenis', 'sapato', 'camisa', 'calça', 'vestido', 'shein', 'zara', 'renner', 'hm', 'blusa', 'shorts', 'cueca', 'meia', 'jaqueta'] },
  { name: 'Educação',    id: 'UUID_EDUCACAO',    keywords: ['curso', 'faculdade', 'livro', 'escola', 'udemy', 'alura', 'certificado', 'mensalidade'] }
];

const descLower = description.toLowerCase();
let categoryId   = 'UUID_OUTROS';
let categoryName = 'Outros';
for (const cat of CATEGORIES) {
  if (cat.keywords.some(kw => descLower.includes(kw) || messageLower.includes(kw))) {
    categoryId   = cat.id;
    categoryName = cat.name;
    break;
  }
}

const now  = new Date();
const month = now.getMonth() + 1;
const year  = now.getFullYear();
const expenseDate = now.toISOString().split('T')[0];

return [{
  json: {
    phone,
    userId: user.id,
    amount,
    description,
    categoryId,
    categoryName,
    month,
    year,
    expenseDate
  }
}];

const expense    = $('Parsear Gasto e Categoria').first().json;
const catExpenses = $('Gastos Mensais Categoria').first().json;
const budgetData  = $('Meta da Categoria').first().json;

const { amount, description, categoryName, phone } = expense;

// Somar todos os gastos da categoria no mês
const expenseList = Array.isArray(catExpenses) ? catExpenses : [];
const categoryTotal = expenseList.reduce((sum, e) => sum + parseFloat(e.amount || 0), 0);

// Pegar meta da categoria
const budgetList  = Array.isArray(budgetData) ? budgetData : [];
const monthlyLimit = budgetList.length > 0 ? parseFloat(budgetList[0].monthly_limit) : 0;

const percentage = monthlyLimit > 0 ? (categoryTotal / monthlyLimit) * 100 : 0;
const remaining  = monthlyLimit - categoryTotal;
const overflow   = categoryTotal - monthlyLimit;

// Templates de resposta por nível de raiva
const responses = {
  low: [
    `Registrado, recruta! Você jogou fora *R$ ${amount.toFixed(2)}* em ${description}.\nTotal em *${categoryName}* esse mês: *R$ ${categoryTotal.toFixed(2)}*. Continua assim não.`,
    `Anotado o desperdício de *R$ ${amount.toFixed(2)}* em ${description}.\nTotal em *${categoryName}* esse mês: *R$ ${categoryTotal.toFixed(2)}*. Ainda tá no controle, mas vai com calma.`
  ],
  medium: [
    `PORRA! Mais *R$ ${amount.toFixed(2)}* em ${description}?!\nVocê já queimou *R$ ${categoryTotal.toFixed(2)}* de *R$ ${monthlyLimit.toFixed(2)}* em *${categoryName}* — isso é *${percentage.toFixed(0)}%* do limite! Segura a onda, recruta!`,
    `Vai tomar vergonha! Já foi *R$ ${categoryTotal.toFixed(2)}* de *R$ ${monthlyLimit.toFixed(2)}* em *${categoryName}*!\n${percentage.toFixed(0)}% do orçamento foi pro lixo. Para de sangrar o bolso!`
  ],
  high: [
    `VAI TOMA NO CU, RECRUTA! ⚠️\n*${percentage.toFixed(0)}%* do limite de *${categoryName}* já foi!\nSó restam *R$ ${remaining.toFixed(2)}* antes do estouro total. PARA DE GASTAR!`,
    `IRRESPONSÁVEL! Você usou *${percentage.toFixed(0)}%* do limite de *${categoryName}*.\nFaltam só *R$ ${remaining.toFixed(2)}* pra explodir o orçamento. SUA MÃE TÁ VENDO, RECRUTA!`
  ],
  over: [
    `🚨 MISSÃO FRACASSADA! Você *ESTOUROU* o limite de *${categoryName}*!\nEra *R$ ${monthlyLimit.toFixed(2)}* e você já torrou *R$ ${categoryTotal.toFixed(2)}*!\nUltrapassou em *R$ ${overflow.toFixed(2)}*! INCOMPETENTE! VAI VENDER O RIM!`,
    `RECRUTA FALIDO! 🚨 O orçamento de *${categoryName}* explodiu!\n*R$ ${overflow.toFixed(2)}* acima do limite! Isso é uma VERGONHA! Vai plantar dinheiro no quintal?!`
  ],
  no_limit: [
    `Anotado! *R$ ${amount.toFixed(2)}* em ${description} registrado em *${categoryName}*.\nTotal do mês nessa categoria: *R$ ${categoryTotal.toFixed(2)}*.\nVocê nem colocou limite aqui, recruta irresponsável. Tá jogando no escuro!`
  ]
};

let toneKey = 'no_limit';
if (monthlyLimit > 0) {
  if (percentage <= 50)       toneKey = 'low';
  else if (percentage <= 80)  toneKey = 'medium';
  else if (percentage <= 100) toneKey = 'high';
  else                         toneKey = 'over';
}

const pool         = responses[toneKey];
const responseText = pool[Math.floor(Math.random() * pool.length)];

return [{ json: { phone, responseText } }];

const routeData     = $('Lógica de Roteamento').first().json;
const monthlyData   = $('Buscar Gastos do Mês').first().json;
const budgetsData   = $('Buscar Metas Usuário').first().json;

const { phone } = routeData;
const expenses  = Array.isArray(monthlyData) ? monthlyData : [];
const budgets   = Array.isArray(budgetsData) ? budgetsData : [];

const months = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const now    = new Date();
const monthName = months[now.getMonth()];
const year      = now.getFullYear();

// Agrupar gastos por categoria
const grouped = {};
for (const exp of expenses) {
  const catName  = (exp.categories && exp.categories.name)  || 'Outros';
  const catEmoji = (exp.categories && exp.categories.emoji) || '💸';
  if (!grouped[catName]) grouped[catName] = { total: 0, emoji: catEmoji };
  grouped[catName].total += parseFloat(exp.amount || 0);
}

// Mapear metas por categoria
const budgetMap = {};
for (const b of budgets) {
  const catName = b.categories && b.categories.name;
  if (catName) budgetMap[catName] = parseFloat(b.monthly_limit || 0);
}

// Montar linhas do relatório
let totalGeral = 0;
const lines = [];
const sortedCats = Object.entries(grouped).sort((a, b) => b[1].total - a[1].total);

for (const [catName, data] of sortedCats) {
  const limit   = budgetMap[catName] || 0;
  const pct     = limit > 0 ? Math.round((data.total / limit) * 100) : null;
  const pctStr  = pct !== null ? ` (${pct}%)` : '';
  const alert   = pct && pct >= 100 ? ' 🔴' : (pct && pct >= 80 ? ' ⚠️' : '');
  const limStr  = limit > 0 ? ` / R$ ${limit.toFixed(2)}` : '';
  lines.push(`${data.emoji} *${catName}*: R$ ${data.total.toFixed(2)}${limStr}${pctStr}${alert}`);
  totalGeral += data.total;
}

let summaryText;
if (lines.length === 0) {
  summaryText = `Situação de *${monthName}/${year}*: ZERO gasto registrado, recruta.\nOu você é milagrosamente frugal, ou esqueceu de me avisar dos gastos. Provavelmente a segunda opção.`;
} else {
  const intro = totalGeral > 3000
    ? `🚨 Relatório de *${monthName}/${year}*, recruta. Prepara o coração:\n\n`
    : `📊 Situação do campo em *${monthName}/${year}*:\n\n`;
  const outro = totalGeral > 3000
    ? `\n\n💸 *TOTAL DESTRUÍDO: R$ ${totalGeral.toFixed(2)}*\n\nTá satisfeito com essa carnificina financeira, recruta?! VAI POUPAR!`
    : `\n\n💸 *TOTAL DO MÊS: R$ ${totalGeral.toFixed(2)}*\n\nPoderia ser pior. Mas poderia ser melhor também. Vai poupar, recruta.`;
  summaryText = intro + lines.join('\n') + outro;
}

return [{ json: { phone, responseText: summaryText } }];

const routeData = $('Lógica de Roteamento').first().json;
const { phone } = routeData;

const respostas = [
  'Fala direito, recruta! Me diz quanto gastou e onde.\nExemplo: *"General, gastei 50 reais no iFood"*',
  'Isso não é ordem que se dá! Me manda o valor e o que comprou.\nExemplo: *"gastei 30 reais no uber"*',
  'Não entendi patavina. Quer ver seus gastos? Manda *"quanto gastei esse mês"*.\nQuer registrar um gasto? Me fala o valor e onde gastou.',
  'Recruta, fala de forma que eu entenda!\nRegistrar gasto: *"gastei X reais em Y"*\nVer resumo: *"quanto gastei esse mês"*'
];

const responseText = respostas[Math.floor(Math.random() * respostas.length)];
return [{ json: { phone, responseText } }];
